 */
function listarPlanes(empresas_planes, sucursales_consumos_agendas, sucursales_consumos_ofertas_laborales) {
    let contenido = empresas_planes.map(empresa_plan => {
        let consumos_empresas = obtenerConsumos(empresa_plan.consumos);
        let lista_consumos_por_sucursal = listarCantidadConsumosSucursales(empresa_plan, sucursales_consumos_agendas, sucursales_consumos_ofertas_laborales);

        let { plan, fecha_vencimiento, precio, estado, vigencia_dias, unidades, conteo_consumos_vacantes, cantidad_usuarios, consumos } = empresa_plan;

        if (!plan && !empresa_plan.plan_credito) {
            return '';
        }
        let suscripcion_ilimitada = !!fecha_vencimiento;

        let fecha_inicio = diferenciaFechasDias((new Date()).toString(), empresa_plan.fecha_inicio) >= 0
            ? empresa_plan.fecha_inicio
            : (new Date()).toString();

        let dias_restantes = suscripcion_ilimitada
            ? diferenciaFechasDias(fecha_inicio, empresa_plan.fecha_vencimiento, false, false)
            : null;

        let unidades_consumidas = empresa_plan.conteo_consumos_agendas ?? 0;
        let ofertas_laborales_consumidas = empresa_plan.conteo_consumos_ofertas_laborales ?? 0;

        return empresa_plan.plan_credito_id === null ? `
            <div class="card my-5">
                <div class="card-body">
                    <div class="row">
                        <div class="col-auto my-auto">${ESTADOS_PLANES[estado.nombre]}</div>
                        <div class="col-auto my-auto">
                            <p class="m-0 text-body-3"><i class="bi ${ICONOS_PLANES_TIPO[plan.tipo_prueba.nombre]} me-2 text-primary text-body-2" 
                             ${crearTooltip({
                                placement: 'top',
                                content: generarTooltipPruebasPlan(
                                    empresa_plan.pruebas,
                                    plan.nombre
                                )
                            })}></i>${plan.tipo_prueba.nombre}</p>
                            <p class="m-0 text-headline-3 fw-bolder">${plan.nombre}</p>
                        </div>
                        <div class="col-auto ms-auto my-auto">
                            <p class="m-0 text-body-3">Costo: ${formatearCOP(precio)}</p>
                        </div>
                        <div class="col-auto my-auto">
                            <div class="dropdown">
                                ${crearBoton({
                                    clases: 'btn-outline-primary btn-circle dropdown-toggle',
                                    texto: '<i class="bi bi-three-dots-vertical"></i>',
                                    data: [{ texto: 'bs-toggle', value: 'dropdown' }]
                                })}
                                <div class="dropdown-menu dropdown-menu-start">
                                    <button class="dropdown-item no-visited" onclick="abrirModalSolicitudRenovacionPlan(${plan.id}, '${plan.nombre}')">
                                        Solicitar renovación
                                    </button>
                                    <button class="dropdown-item no-visited" onclick="abrirFacturaPlan('${empresa_plan?.archivos[0]?.id}')">
                                        Ver factura
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                    <div class="table-responsive mt-4">
                        <table class="table">
                            <tbody>
                                <tr id="contenedor_plan_padre">
                                    <td class="py-0 my-0 border-0">
                                        <div class="card bg-gray-90 border-0">
                                            <div class="card-body py-2">
                                                <div class="row">
                                                    <!-- <div class="col-auto my-auto">
                                                        ${crearBoton({
                                                            clases: 'btn-text-gray text-label-2',
                                                            texto: `Sucursales: ${consumos_empresas.length} <i class="bi bi-caret-down-fill"></i>`,
                                                            onclick: `toggleSucursalesList('${empresa_plan.id + '_' + empresa_plan.plan_id + '_' + empresa_plan.numero_factura}', this)`,
                                                        })}
                                                    </div> -->
                                                    <div class="col my-auto">
                                                        <div class="card bg-white border-0">
                                                            <div class="card-body py-2 px-8">
                                                                <div class="row">
                                                                    <div class="col-4 pe-8" ${crearTooltip({
                                                                        placement: 'top',
                                                                        content: generarTooltipConsumosPruebas(empresa_plan?.consumos ?? [], unidades_consumidas ?? 0, empresa_plan.pruebas ?? [])
                                                                    })}>
                                                                        ${crearProgressBarTemplate('Unidades', 'box', unidades_consumidas, obtenerLimiteConsumo(empresa_plan, 'unidades'), true)}
                                                                    </div>
                                                                    <div class="col-4 pe-8">
                                                                        ${crearProgressBarTemplate('Vacantes', 'briefcase', conteo_consumos_vacantes, obtenerLimiteConsumo(empresa_plan, 'cantidad_ofertas_laborales'), true)}
                                                                    </div>
                                                                    <div class="col-4">
                                                                        ${crearProgressBarTemplate('Usuarios', 'person', total_usuarios, cantidad_usuarios, true)}
                                                                    </div>
                                                                </div>
                                                            </div>
                                                        </div>
                                                    </div>
                                                    <div class="col-auto my-auto ps-0">
                                                        ${crearBoton({
                                                            tooltip: `${crearTooltip({
                                                                placement: `top`,
                                                                content: `Detalle de consumo`,
                                                                toggle: `popover`,
                                                            })}`,
                                                            clases: 'btn-text-primary btn-circle p-2',
                                                            texto: '<i class="bi bi-eye text-headline-4"></i>',
                                                            onclick: `abrirModalConsumos(${empresa_plan.id}, '${plan.nombre}', '${plan.tipo_prueba.nombre}')`,
                                                        })}
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </td>
                                </tr>
                                ${lista_consumos_por_sucursal}
                            </tbody>
                        </table>
                    </div>
                    <div class="row mt-5">
                        <div class="col-auto">
                            <p class="text-label-2">
                                <span class="me-3"><i class="bi bi-clock me-2"></i>Duración: ${empresa_plan.vigencia_dias ? `${empresa_plan.vigencia_dias} día(s)` : 'Sin vigencia'}</span>
                                <span class="">quedan ${ suscripcion_ilimitada ? `${parseInt(dias_restantes) >= 0 ? `${parseInt(dias_restantes)}` : '0'}` : ''} de ${empresa_plan.vigencia_dias ? `${empresa_plan.vigencia_dias}` : '0'} días</span>
                            </p>
                        </div>
                        <div class="col-auto ms-auto">
                            <p class="text-label-2">
                                <span class="me-4">Vigencia</span>
                                <span class="me-4"><i class="bi bi-circle-fill small-1 text-green-cta me-2"></i>${convertirFecha(empresa_plan.fecha_inicio)}</span>
                                ${ suscripcion_ilimitada ? `<span class=""><i class="bi bi-circle-fill small-1 text-danger me-2"></i>${convertirFecha(empresa_plan.fecha_vencimiento)}</span>` : '' }
                            </p>
                        </div>
                    </div>
                </div>
            </div>
        ` : `
            <div class="card my-5">
                <div class="card-body">
                    <div class="row">
                        <div class="col-auto my-auto">${ESTADOS_PLANES[estado.nombre]}</div>
                        <div class="col-auto my-auto">
                            <p class="m-0 text-body-3"><img src="/iconos/icono_ia_azul.svg" alt="IA" class="me-2">Plan de Créditos</p>
                            <p class="m-0 text-headline-3 fw-bolder">${empresa_plan.plan_credito.nombre}</p>
                        </div>
                        <div class="col-auto ms-auto my-auto">
                            <p class="m-0 text-body-3">Costo: ${formatearCOP(empresa_plan.plan_credito.precio)}</p>
                        </div>
                        <div class="col-auto my-auto">
                            <div class="dropdown">
                                ${crearBoton({
                                    clases: 'btn-outline-primary btn-circle dropdown-toggle',
                                    texto: '<i class="bi bi-three-dots-vertical"></i>',
                                    data: [{ texto: 'bs-toggle', value: 'dropdown' }]
                                })}
                                <div class="dropdown-menu dropdown-menu-start">
                                    <button class="dropdown-item no-visited" onclick="abrirModalSolicitudRenovacionPlan(${empresa_plan.plan_credito.id}, '${empresa_plan.plan_credito.nombre}', 'plan_credito')">
                                        Solicitar renovación
                                    </button>
                                    <button class="dropdown-item no-visited" onclick="abrirFacturaPlan('${empresa_plan?.archivos[0]?.id}')">
                                        Ver factura
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div class="table-responsive mt-4">
                        <table class="table">
                            <tbody>
                                <tr id="contenedor_plan_padre">
                                    <td class="py-0 my-0 border-0">
                                        <div class="card bg-gray-90 border-0">
                                            <div class="card-body py-2">
                                                <div class="row">
                                                    <!-- <div class="col-auto my-auto">
                                                        ${crearBoton({
                                                            clases: 'btn-text-gray text-label-2',
                                                            texto: `Sucursales: ${consumos_empresas.length} <i class="bi bi-caret-down-fill"></i>`,
                                                            onclick: `toggleSucursalesList('${empresa_plan.id + '_' + empresa_plan.plan_id + '_' + empresa_plan.numero_factura}', this)`,
                                                        })}
                                                    </div> -->
                                                    <div class="col my-auto">
                                                        <div class="card bg-white border-0">
                                                            <div class="card-body py-2 px-8">
                                                                <div class="row">
                                                                    <div class="col-4 pe-8">
                                                                        ${crearProgressBarTemplate('Créditos disponibles', '/iconos/icono_ia.svg', empresa_plan.creditos_consumidos ?? 0, empresa_plan.plan_credito.creditos ?? 0, true)}
                                                                    </div>
                                                                </div>
                                                            </div>
                                                        </div>
                                                    </div>
                                                    <div class="col-auto my-auto ps-0">
                                                        ${crearBoton({
                                                            tooltip: `${crearTooltip({
                                                                placement: `top`,
                                                                content: `Ver detalle consumo`,
                                                            })}`,
                                                            clases: 'btn-text-primary btn-circle p-2',
                                                            texto: '<i class="bi bi-eye text-headline-4"></i>',
                                                            onclick: `abrirModalConsumosCreditos(${empresa_plan.empresa_id}, ${empresa_plan.id}, '${empresa_plan.plan_credito.nombre}')`,
                                                        })}
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </td>
