            </div>
        `;
    }).join('');

    $('#listado-planes').html(contenido);
    inicializarTooltips();
}

/**
 * Crea el componente HTML de los progress bars de los consumos.
 *
 * @param {string} label Etiqueta del progress bar.
 * @param {string} icono Icono del progress bar.
 * @param {number} valor Valor actual del consumo.
 * @param {number} total Valor total del consumo.
 * @param {boolean} un_text Booleano para mostrar o no el texto.
 * @returns {string} HTML del progress bar.
 * @author Andres Morales
 * @author Andres Gonzalez
 */
function crearProgressBarTemplate(label, icono, valor, total, un_text) {
    let icono_html = '';
    if (icono) {
        if (icono.startsWith('/') || icono.includes('.svg')) {
            icono_html = `<img src="${icono}" alt="${label}" class="me-2">`;
        } else {
            icono_html = `<i class="bi bi-${icono} text-headline-5 me-2"></i>`;
        }
    }
    return `
        ${un_text ? '<p class="text-label-1 mb-1">' : ''}${icono_html}${label}${un_text ? '</p>' : ''}
        ${crearProgressBar({
            label: `${valor}/${total ?? 0}`,
            height: '8px',
            porcentaje: { porcentaje: (valor / (total ?? 1)) * 100, texto: false }
        })}
    `;
}

/**
 * Retornar el componente html de la lista de cantidades de consumos agrupados por sucursal.
 *
 * @param {Object} empresa_plan Registro de la tabla empresas_planes.
 * @param {array} sucursales_consumos_agendas Arreglo de los conteos de los consumos de agendas de las sucursales de la empresa.
 * @param {array} sucursales_consumos_ofertas_laborales Arreglo de los conteos de los consumos de ofertas laborales de las sucursales de la empresa.
 * @returns {string}
 * @author Andres Morales
 * @author Fahibram Cárcamo
 * @author Sergio Vargas
 */
function listarCantidadConsumosSucursales (empresa_plan, sucursales_consumos_agendas, sucursales_consumos_ofertas_laborales) {
    if (!empresa_plan.plan) {
        return '';
    }
    return sucursales.map(sucursal => {
        let conteos_consumos_agendas_sucursal = sucursales_consumos_agendas.find(sucursal_busqueda => sucursal_busqueda.id === sucursal.id);
        let conteos_consumos_ofertas_laborales_sucursal = sucursales_consumos_ofertas_laborales.find(sucursal_busqueda => sucursal_busqueda.id === sucursal.id);

        let total_agendas_consumidas_sucursal = conteos_consumos_agendas_sucursal?.consumos_agrupados_por_empresa_plan
            ?.find(conteo => conteo.empresa_plan_id === empresa_plan.id)
            ?.conteo_consumos ?? 0;

        let total_ofertas_laborales_consumidas_sucursal = conteos_consumos_ofertas_laborales_sucursal?.consumos_agrupados_por_empresa_plan
            ?.find(conteo => conteo.empresa_plan_id === empresa_plan.id)
            ?.conteo_consumos ?? 0;

        let total_usuarios_sucursal = obtenerTotalUsuarios(sucursal);
        let plan = empresa_plan.plan;

        return `
            <tr class="contenedor_plan_hijo_${empresa_plan.id}_${plan.id}_${empresa_plan.numero_factura} d-none">
                <td class="py-0 my-0">
                    <div class="card border-0">
                        <div class="card-body py-2 px-10">
                            <div class="row">
                                <div class="col-2 my-auto text-body-3 text-wrap">
                                    ${sucursal.nombre_comercial}
                                </div>
                                <div class="col my-auto">
                                    <div class="card bg-white border-0">
                                        <div class="card-body py-2">
                                            <div class="row">
                                                <div class="col-4 px-7">
                                                    ${
                                                        crearProgressBarTemplate(
                                                            'Unidades',
                                                            'box',
                                                            total_agendas_consumidas_sucursal,
                                                            plan.unidades,
                                                            false
                                                        )
                                                    }
