   759→                            }
   760→                        ]);
   761→                }
   762→            ])
   763→            ->when(
   764→                $request->filled('estado_id') && !in_array($request->estado_id, [3, 8]),
   765→                fn($consulta_estado) => $consulta_estado->where('estado_id', $request->estado_id)
   766→            )
   767→            ->whereNotIn('estado_id', [3, 8])
   768→            ->when(
   769→                $request->filled('prueba_id'),
