   793→            ->when($request->filled('fecha_vencimiento'), function ($consulta, $buscar) use ($request) {
   794→                $fecha_inicio = $request->fecha_vencimiento;
   795→                $fecha_fin    = $request->fecha_vencimiento;
   796→
   797→                if (strpos($request->fecha_vencimiento, ' a ') !== false) {
