   802→
   803→                $consulta->whereBetween(DB::raw('DATE(fecha_vencimiento)'), [$fecha_inicio, $fecha_fin]);
   804→            })
   805→            ->when($request->filled('fecha_inicio'), function ($consulta, $buscar) use ($request) {
   806→                $fecha_inicio = $request->fecha_inicio;
   807→                $fecha_fin    = $request->fecha_inicio;
