   821→            ->when($request->filled('tipo_activacion'), function ($consulta_tipo_activacion) use ($request) {
   822→                if ($request->tipo_activacion === 'compra') {
   823→                    $consulta_tipo_activacion->whereNotExists(function ($subconsulta) {
   824→                        $subconsulta->select(DB::raw(1))
   825→                            ->from('empresas_planes AS empresas_planes_subconsulta')
   826→                            ->whereColumn('empresas_planes_subconsulta.plan_id', 'empresas_planes.plan_id')
   827→                            ->whereColumn('empresas_planes_subconsulta.empresa_id', 'empresas_planes.empresa_id')
   828→                            ->whereColumn('empresas_planes_subconsulta.id', '<>', 'empresas_planes.id');
   829→                    });
   830→                } elseif ($request->tipo_activacion === 'recompra') {
   831→                    $consulta_tipo_activacion->whereExists(function ($subconsulta) {
