  1004→    public function historialComprasCreditos(int $empresa_id, Request $request): Collection {
  1005→        return $this->modelo::select(
  1006→            'id',
  1007→            'empresa_id',
  1008→            'plan_credito_id',
  1009→            'estado_id',
