  1012→            'fecha_vencimiento',
  1013→            'precio',
  1014→            'porcentaje_descuento',
  1015→            'numero_factura',
  1016→            'comentario',
  1017→            'created_at'
  1018→        )
  1019→        ->with([
  1020→            'planCredito:id,nombre,creditos,precio,porcentaje_descuento,fecha_inicio_promocion,fecha_fin_promocion',
  1021→            'estado:id,nombre',
  1022→            'archivos' => function ($archivos) {
  1023→                $archivos->select('id', 'modelo', 'modelo_id', 'nombre', 'ruta', 'created_at')
  1024→                    ->orderBy('created_at', 'DESC');
  1025→            }
  1026→        ])
  1027→        ->withSum('consumosCreditos as creditos_consumidos', 'creditos')
  1028→        ->where('empresa_id', $empresa_id)
  1029→        ->whereNotNull('plan_credito_id')
  1030→        ->when($request->filled('estado_id'), fn($consulta) => $consulta->where('estado_id', $request->estado_id))
  1031→        ->when(
  1032→            $request->filled('duracion') && $request->duracion === 'con_tiempo',
  1033→            fn($consulta) => $consulta->whereNotNull('fecha_vencimiento')
  1034→        )
  1035→        ->when(
  1036→            $request->filled('duracion') && $request->duracion === 'sin_tiempo',
  1037→            fn($consulta) => $consulta->whereNull('fecha_vencimiento')
  1038→        )
  1039→        ->when(
  1040→            $request->filled('fecha_vencimiento_desde'),
  1041→            fn($consulta) => $consulta->where('fecha_vencimiento', '>=', $request->fecha_vencimiento_desde)
  1042→        )
